import json

with open('json/circuits.json', 'r') as f:
    data = json.load(f)

# Extract circuitId and country for all circuits
circuits = []
for record in data['records']:
    circuits.append({
        'circuitId': record['circuitId'],
        'country': record['country']
    })

print(f"Total circuits: {len(circuits)}")
for c in circuits[:15]:
    print(c)
